css:
.tg  {border-collapse:collapse;border-spacing:0;}
.tg td{border-color:black;border-style:solid;border-width:1px;font-family:Arial, sans-serif;font-size:10px;
  overflow:hidden;padding:10px 5px;word-break:normal;}
.tg th{border-color:black;border-style:solid;border-width:1px;font-family:Arial, sans-serif;font-size:10px;
  font-weight:normal;overflow:hidden;padding:10px 5px;word-break:normal;}
.tg .tg-0lax{text-align:left;vertical-align:top}

.print-format td, .print-format th {
    vertical-align: top !important;
    padding: 3px !important;
}
.table-bordered tr,th,td {
    border: 1px solid #161414!important;
    page-break-inside: avoid !important;
    table-layout:fixed;
}
.table table-bordered table-hover{
    width:100%;
}
.letter-head{
   
}
h2{
    display:none!important;
}
.print-heading{
    border-bottom: 0px solid #d1d8dd;
    margin-bottom:10px;
    padding-bottom:0px!important;
}
[document-status] {
    margin-bottom: 0px;
     display:none;
}
table.table.table-bordered {
    width:100%;
    border-collapse: collapse;
    border-spacing: 0;
}
